const PREFIX_FREED: u8 = 3;

const WL_RELEASES: [usize; 9] = [6, 18, 30, 42, 54, 66, 78, 90, 102]; // index 0 = prefix
struct WlPacked { phys: Vec<Option<QubitId>>, coins: [Option<crate::circuit::BitId>; 3], fwire: QubitId }
thread_local! {
    static WL_STATE: std::cell::RefCell<std::collections::BTreeMap<usize, WlPacked>> = const { std::cell::RefCell::new(std::collections::BTreeMap::new()) };
}
fn wl_trace() -> bool { std::env::var("ROOM_TRACE").is_ok_and(|v| v == "1") }
fn wl_tid_ticks(tid: usize) -> [usize; 3] { let (g, r) = (tid / 2, tid % 2); let t1 = 6 * g + r; [t1, t1 + 2, t1 + 4] }
/// Raw wires of block b in the codec's local order; also the record keys they come from.
fn wl_gather(b: usize) -> Vec<QubitId> {
    let tids: Vec<usize> = if b == 0 { vec![0, 1] } else { (2 + 4 * (b - 1)..6 + 4 * (b - 1)).collect() };
    let mut w = Vec::new();
    for &tid in &tids {
        let f = A2_REC.with(|r| r.borrow().get(&tid).copied()).unwrap_or_else(|| panic!("WL codec: field {tid}"));
        w.push(f[0].unwrap_or_else(|| panic!("WL codec: f0 {tid}")));
        w.push(f[1].unwrap_or_else(|| panic!("WL codec: f1 {tid}")));
        let ts = wl_tid_ticks(tid);
        for (k, &t) in ts.iter().enumerate() {
            if tid == 0 && k == 0 { continue; } // tick 0 is not an A tick: no c1 cell (short word f0,f1,c2,c3)
            w.push(a2_cell(t).unwrap_or_else(|| panic!("WL codec: cell {t} (tid {tid})")));
        }
    }
    w
}
/// Take the block's wires out of the record maps (any read while packed panics) / put them back.
fn wl_detach(b: usize, attach: Option<&[QubitId]>) {
    let tids: Vec<usize> = if b == 0 { vec![0, 1] } else { (2 + 4 * (b - 1)..6 + 4 * (b - 1)).collect() };
    let mut i = 0;
    for &tid in &tids {
        A2_REC.with(|r| { let mut r = r.borrow_mut(); let f = r.get_mut(&tid).unwrap();
            match attach { Some(w) => { *f = [Some(w[i]), Some(w[i + 1])]; } None => { *f = [None, None]; } } });
        i += 2;
        for (k, &t) in wl_tid_ticks(tid).iter().enumerate() {
            if tid == 0 && k == 0 { continue; }
            A2_CELLS.with(|m| { let mut m = m.borrow_mut();
                match attach { Some(w) => { m.insert(t, w[i]); } None => { m.remove(&t); } } });
            i += 1;
        }
    }
}
fn wl_run(c: &mut Builder, ops: &[WlOp], phys: &mut Vec<Option<QubitId>>, coins: &mut [Option<crate::circuit::BitId>; 3]) {
    let mut fresh: std::collections::BTreeMap<u8, crate::circuit::BitId> = std::collections::BTreeMap::new();
    let q = |phys: &Vec<Option<QubitId>>, i: u8| phys[i as usize].unwrap_or_else(|| panic!("WL codec: local wire {i} not live"));
    for op in ops {
        match *op {
            WlOp::X(a) => c.x(q(phys, a)),
            WlOp::Cx(a, t) => c.cx(q(phys, a), q(phys, t)),
            WlOp::Ccx(a, b, t) => c.ccx(q(phys, a), q(phys, b), q(phys, t)),
            WlOp::Swap(a, b) => c.swap(q(phys, a), q(phys, b)),
            WlOp::Alloc(a) => { assert!(phys[a as usize].is_none()); phys[a as usize] = Some(c.alloc_qubit()); }
            WlOp::Free(a) => { let w = q(phys, a); c.release_clean(w); phys[a as usize] = None; }
            WlOp::Hmr(a, k) => {
                let bit = if k < 3 { assert!(coins[k as usize].is_none(), "WL codec: retained coin reused"); let b = c.alloc_bit(); coins[k as usize] = Some(b); b }
                          else { *fresh.entry(k).or_insert_with(|| c.alloc_bit()) };
                c.hmr(q(phys, a), bit);
            }
            WlOp::Zif(a, k) => { let bit = if k < 3 { coins[k as usize].expect("WL codec: retained coin") } else { fresh[&k] }; c.z_if(q(phys, a), bit); }
            WlOp::Czif(a, b, k) => { let bit = if k < 3 { coins[k as usize].expect("WL codec: retained coin") } else { fresh[&k] }; c.cz_if(q(phys, a), q(phys, b), bit); }
            WlOp::Cczif(a, b, t, k) => { let bit = if k < 3 { coins[k as usize].expect("WL codec: retained coin") } else { fresh[&k] }; c.ccz_if(q(phys, a), q(phys, b), q(phys, t), bit); }
        }
    }
    for (_, b) in fresh { c.free_bit(b); }
}
fn wl_pack(c: &mut Builder, b: usize) {
    let w = wl_gather(b);
    let (commit, freed) = if b == 0 { (PREFIX_COMMIT, PREFIX_FREED) } else { (ORDINARY_COMMIT, ORDINARY_FREED) };
    assert_eq!(w.len(), if b == 0 { 9 } else { 20 });
    let (a0, e0) = (c.active_qubits(), c.expected_total());
    let mut phys: Vec<Option<QubitId>> = vec![None; 23];
    for (i, &x) in w.iter().enumerate() { phys[i] = Some(x); }
    // the codec frees local `freed` (a k2 cell); its wire id is a tape letter, so move the zero onto local 0's f0 wire
    let mut coins = [None; 3];
    let (_, peak) = c.r3_peak(|c| {
        // the freed local is measured and released inside the op list; re-route: run the list with the release deferred
        let n = commit.len();
        let last_free = commit.iter().rposition(|o| matches!(o, WlOp::Free(x) if *x == freed)).expect("WL codec: freed release");
        wl_run(c, &commit[..last_free], &mut phys, &mut coins);
        assert!(last_free + 1 == n || commit[last_free + 1..].iter().all(|o| !matches!(o, WlOp::Free(_) | WlOp::Alloc(_))));
        let (zw, f0w) = (phys[freed as usize].unwrap(), phys[0].unwrap());
        c.swap(zw, f0w); // the zero now sits on the f0 wire, local 0's data on the k2 cell's wire
        phys[0] = Some(zw); phys[freed as usize] = None;
        c.release_clean(f0w);
        wl_run(c, &commit[last_free + 1..], &mut phys, &mut coins);
        WL_STATE.with(|s| { assert!(s.borrow_mut().insert(b, WlPacked { phys: phys.clone(), coins, fwire: f0w }).is_none(), "WL codec: block {b} packed twice"); });
    });
    wl_detach(b, None);
    if wl_trace() { eprintln!("WL_CODEC pack b={b} phase={} active={a0}->{} peak={peak} cost={:.1}", c.phase_name(), c.active_qubits(), c.expected_total() - e0); }
}
fn wl_unpack(c: &mut Builder, b: usize) {
    let WlPacked { mut phys, mut coins, fwire: _ } = WL_STATE.with(|s| s.borrow_mut().remove(&b)).unwrap_or_else(|| panic!("WL codec: block {b} not packed"));
    let (pop, freed) = if b == 0 { (PREFIX_POP, PREFIX_FREED) } else { (ORDINARY_POP, ORDINARY_FREED) };
    let (a0, e0) = (c.active_qubits(), c.expected_total());
    let (_, peak) = c.r3_peak(|c| {
        wl_run(c, pop, &mut phys, &mut coins);
        // local 0's data (f0) sits on the k2 cell's wire, local `freed` (the k2 cell value) on the fresh wire: swap back
        let (cw, nw) = (phys[0].unwrap(), phys[freed as usize].unwrap());
        c.swap(cw, nw);
        phys[0] = Some(nw); phys[freed as usize] = Some(cw);
    });
    for b2 in coins.iter().flatten() { c.free_bit(*b2); }
    let n = if b == 0 { 9 } else { 20 };
    let w: Vec<QubitId> = (0..n).map(|i| phys[i].expect("WL codec: restored wire")).collect();
    assert!(phys[n..].iter().all(|x| x.is_none()));
    wl_detach(b, Some(&w));
    if wl_trace() { eprintln!("WL_CODEC pop b={b} phase={} active={a0}->{} peak={peak} cost={:.1}", c.phase_name(), c.active_qubits(), c.expected_total() - e0); }
}
/// divide, after the payload-only pass: pack every block released by `upto`.
pub(super) fn wl_codec_pack_upto(c: &mut Builder, upto: usize) {
    if !WL_CODEC || !a2_code() { return; }
    for (b, &r) in WL_RELEASES.iter().enumerate() { if r <= upto { wl_pack(c, b); } }
}
/// start of fwd_tick(t): divide fused ticks and multiply rail-only ticks pack the block released at t.
pub(super) fn wl_codec_fwd(c: &mut Builder, t: usize, fused: bool) {
    if !WL_CODEC || !a2_code() { return; }
    let ph = c.phase_name();
    if (ph == "divide" && fused) || (ph == "multiply" && !fused) {
        for (b, &r) in WL_RELEASES.iter().enumerate() {
            let due = if ph == "divide" { r == t && r > lf_reorder(false) } else { r == t };
            if due { wl_pack(c, b); }
        }
    }
}
/// start of rev_tick(t): divide rail-only reverse pops every block at its last tick; multiply revF pops blocks >= 54.
pub(super) fn wl_codec_rev(c: &mut Builder, t: usize, fused: bool) {
    if !WL_CODEC || !a2_code() { return; }
    let ph = c.phase_name();
    for (b, &r) in WL_RELEASES.iter().enumerate() {
        let due = (ph == "divide" && !fused && r - 1 == t) || (ph == "multiply" && fused && r >= 54 && r - 1 == t);
        if due { wl_unpack(c, b); }
    }
}
/// multiply, between the revF loop and the payload-only reverse pass: pop the rest.
pub(super) fn wl_codec_unpack_rest(c: &mut Builder) {
    if !WL_CODEC || !a2_code() { return; }
    let left: Vec<usize> = WL_STATE.with(|s| s.borrow().keys().copied().collect());
    for b in left.into_iter().rev() { wl_unpack(c, b); }
}
pub(super) fn wl_codec_assert_empty(where_: &str) {
    if !WL_CODEC { return; }
    WL_STATE.with(|s| assert!(s.borrow().is_empty(), "WL codec: blocks still packed at {where_}"));
}
